import numpy as np
import pandas as pd
import warnings

def r_data_frame(*args, **kwargs):
    """
    Python reproduction of R's data.frame function.
    """
    row_names = kwargs.pop('row_names', None)
    check_rows = kwargs.pop('check_rows', False)
    check_names = kwargs.pop('check_names', True)
    fix_empty_names = kwargs.pop('fix_empty_names', True)
    strings_as_factors = kwargs.pop('stringsAsFactors', False)

    # Handle the case where no data arguments are provided
    if not args and not kwargs:
        if row_names is not None:
            # Basic R validation for row.names
            rn = np.array(row_names, dtype=object)
            if np.any(pd.isna(rn)):
                raise ValueError("row names contain missing values")
            if len(rn) != len(np.unique(rn)):
                raise ValueError(f"duplicate row.names: {', '.join(map(str, np.unique(rn[np.unique(rn, return_counts=True)[1] > 1])))}")
            return pd.DataFrame(index=rn.tolist())
        else:
            return pd.DataFrame()

    # Combine positional and keyword arguments
    # In R, data.frame(a=1, b=2) is like a list of named arguments
    data_dict = {}

    # Process positional args (which may be named in the R call but are passed as *args here if not captured by kwargs)
    # However, in the provided R source, ... is the primary input.
    # We simulate the R data.frame behavior by collecting all inputs.

    # Extract names for the inputs
    inputs = []
    input_names = []

    # In Python, if they are passed as kwargs, they are named. 
    # If passed as *args, they are unnamed unless we have a way to know.
    # R's `...` captures both.

    # Since we cannot get the exact expression names from Python's *args, 
    # we follow pandas' logic which is close to R's.

    # Gather all data
    all_data = {}

    # Handle *args (unnamed)
    for i, val in enumerate(args):
        name = f"V{i+1}" # Default R-like name if missing
        all_data[name] = val

    # Handle **kwargs (named)
    for name, val in kwargs.items():
        all_data[name] = val

    # R's data.frame is essentially a list of vectors.
    # We need to handle recycling (the "differing number of rows" error)

    processed_cols = {}
    max_len = 0

    # First pass: determine lengths and convert to arrays
    for name, val in all_data.items():
        # Convert to numpy array to handle R-like vectorization
        if isinstance(val, (list, np.ndarray, pd.Series)):
            arr = np.array(val, dtype=object)
        elif np.isscalar(val):
            arr = np.array([val], dtype=object)
        else:
            # Handle other types (like DataFrames passed into data.frame)
            if isinstance(val, pd.DataFrame):
                # If a DataFrame is passed, its columns are expanded
                # This is a complex part of R's data.frame
                for col in val.columns:
                    processed_cols[f"{name}.{col}" if name != "V1" else col] = val[col].values
                continue
            arr = np.array([val], dtype=object)

        processed_cols[name] = arr
        max_len = max(max_len, len(arr))

    # Second pass: Recycling and validation
    final_data = {}
    for name, arr in processed_cols.items():
        n = len(arr)
        if n == 0:
            # R handles 0-length vectors by creating an empty df
            # but if other columns have length, this is usually an error or 0-row df
            final_data[name] = np.array([], dtype=object)
            continue

        if n != max_len:
            if max_len % n == 0:
                # Recycle
                final_data[name] = np.tile(arr, max_len // n)
            else:
                raise ValueError(f"arguments imply differing number of rows: {n}, {max_len}")
        else:
            final_data[name] = arr

    # Construct DataFrame
    df = pd.DataFrame(final_data)

    # Handle row.names
    if row_names is not None:
        # If row_names is a single value and max_len > 1, R checks if it's a column name
        if np.isscalar(row_names) or (isinstance(row_names, (list, np.ndarray)) and len(row_names) == 1):
            rn_val = row_names[0] if isinstance(row_names, (list, np.ndarray)) else row_names
            if rn_val in df.columns:
                df.index = df[rn_val].values
                df = df.drop(columns=[rn_val])
            else:
                # In R, if it's not a column, it's treated as a literal name for the first row
                # but usually it's an error if length doesn't match.
                if max_len != 1:
                    # This is a simplification of R's logic
                    pass 
        else:
            rn = np.array(row_names, dtype=object)
            if len(rn) != max_len:
                raise ValueError("row names supplied are of the wrong length")
            if np.any(pd.isna(rn)):
                raise ValueError("row names contain missing values")
            if len(rn) != len(np.unique(rn)):
                raise ValueError("duplicate row.names")
            df.index = rn

    # Handle check_names / make.names
    if check_names:
        # pandas doesn't have a direct 'make.names', so we approximate 
        # by ensuring names are strings and unique (pandas does uniqueness automatically)
        df.columns = [str(c) for c in df.columns]

    # Reset index if it's default (R's 1-based vs Python's 0-based is handled by the harness)
    # But the return must be the DataFrame object.

    return df
